import{_ as e,o as t,c as r,a4 as s}from"./chunks/framework.vNSRaLQv.js";const g=JSON.parse('{"title":"EasyTier 组网折腾记录","description":"","frontmatter":{"title":"EasyTier 组网折腾记录","date":"2026-06-28T00:00:00.000Z"},"headers":[],"relativePath":"posts/EasyTier折腾记录.md","filePath":"posts/EasyTier折腾记录.md"}'),i={name:"posts/EasyTier折腾记录.md"};function o(n,a,l,d,p,h){return t(),r("div",null,[...a[0]||(a[0]=[s(`<h1 id="easytier-组网折腾记录" tabindex="-1">EasyTier 组网折腾记录 <a class="header-anchor" href="#easytier-组网折腾记录" aria-label="Permalink to &quot;EasyTier 组网折腾记录&quot;">​</a></h1><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>想用 EasyTier 做异地组网，电脑和手机之间互相访问，跑 Moonlight 串流。之前折腾了好几个竞品，最后才选了 EasyTier。</p><h2 id="之前折腾过的竞品" tabindex="-1">之前折腾过的竞品 <a class="header-anchor" href="#之前折腾过的竞品" aria-label="Permalink to &quot;之前折腾过的竞品&quot;">​</a></h2><h3 id="zerotier" tabindex="-1">ZeroTier <a class="header-anchor" href="#zerotier" aria-label="Permalink to &quot;ZeroTier&quot;">​</a></h3><p><strong>优点：</strong> 免费 25 台设备，社区活跃，有自建 Planet 控制器的方案。</p><p><strong>放弃原因：</strong> 权限管理太拉胯。没有细粒度的端口级 ACL，要么全开要么全关。Free 版 Flow Rules 在新版 Central 被砍了（要付费），Legacy Central 能用但界面古老。设备授权要手动去网页打勾，朋友多了管理麻烦。</p><h3 id="tailscale" tabindex="-1">Tailscale <a class="header-anchor" href="#tailscale" aria-label="Permalink to &quot;Tailscale&quot;">​</a></h3><p><strong>优点：</strong> ACL 权限管理做得最好，deny-by-default，按人/设备/端口控制。MagicDNS 自动给设备分配域名。<code>tailscale serve</code> 一条命令暴露服务。基于 WireGuard，性能好。</p><p><strong>放弃原因：</strong></p><ol><li>免费版只有 3 个用户，朋友超过 3 个就得付费或自建 Headscale</li><li>协调服务器在国外， DERP 中继服务器也大多在国外，国内延迟高</li><li>自建 DERP 需要国内 VPS + 域名备案，嫌麻烦</li><li>登录要用 Google/GitHub 账号，朋友不愿意给账号密码（后来发现可以邀请，但已经放弃研究了）</li></ol><h3 id="wireguard-原生" tabindex="-1">WireGuard（原生） <a class="header-anchor" href="#wireguard-原生" aria-label="Permalink to &quot;WireGuard（原生）&quot;">​</a></h3><p><strong>优点：</strong> 内核级 VPN，性能最强，延迟最低。完全自主可控。</p><p><strong>放弃原因：</strong> 配置太复杂。每台设备都要手动生成密钥、写配置文件、配 IP 地址。异地组网还要自己搞公网 IP 或者端口映射。不适合小白和朋友组网场景。</p><h3 id="花生壳-cpolar-ngrok" tabindex="-1">花生壳 / cpolar / ngrok <a class="header-anchor" href="#花生壳-cpolar-ngrok" aria-label="Permalink to &quot;花生壳 / cpolar / ngrok&quot;">​</a></h3><p><strong>优点：</strong> 国内服务商，中文界面，注册就能用。</p><p><strong>放弃原因：</strong> 免费版限速严重（花生壳 1Mbps），端口数限制，不适合需要稳定高速的场景。本质是中心化中转，延迟不可控。</p><h2 id="最终选择-easytier-的理由" tabindex="-1">最终选择 EasyTier 的理由 <a class="header-anchor" href="#最终选择-easytier-的理由" aria-label="Permalink to &quot;最终选择 EasyTier 的理由&quot;">​</a></h2><ol><li><strong>免费无设备限制</strong> — 不像 Tailscale 限制 3 用户</li><li><strong>去中心化</strong> — 不依赖单一服务器，节点之间 P2P 直连</li><li><strong>国内公共节点多</strong> — 社区维护，大部分是国内服务器</li><li><strong>GUI 操作</strong> — 不像 WireGuard 那样要手写配置文件</li><li><strong>UDP+TCP 双通道</strong> — NAT 穿透率 98%，比 ZeroTier 的 UDP 单通道强</li></ol><h2 id="踩过的坑" tabindex="-1">踩过的坑 <a class="header-anchor" href="#踩过的坑" aria-label="Permalink to &quot;踩过的坑&quot;">​</a></h2><h3 id="_1-easytier-gui-连不上任何公共服务器" tabindex="-1">1. EasyTier GUI 连不上任何公共服务器 <a class="header-anchor" href="#_1-easytier-gui-连不上任何公共服务器" aria-label="Permalink to &quot;1. EasyTier GUI 连不上任何公共服务器&quot;">​</a></h3><p><strong>症状：</strong> 打开 EasyTier GUI，添加公共节点后一直转圈，连不上。</p><p><strong>原因：</strong> Clash Verge 后台服务没关干净。虽然界面退出了，但 <code>clash_verge_service</code>（PID 4624）还在 Windows 服务里跑着，TUN 模式残留路由干扰了 EasyTier 的出站连接。</p><p><strong>解决：</strong> <code>Stop-Service -Name &quot;clash_verge_service&quot; -Force</code> 强制停掉服务。</p><p><strong>教训：</strong> 退出 Clash Verge 界面 ≠ 关掉服务，要去 Windows 服务管理器里确认。</p><h3 id="_2-公共服务器地址填错" tabindex="-1">2. 公共服务器地址填错 <a class="header-anchor" href="#_2-公共服务器地址填错" aria-label="Permalink to &quot;2. 公共服务器地址填错&quot;">​</a></h3><p><strong>症状：</strong> 按官方 README 填 <code>tcp://public.easytier.top:11010</code>，DNS 解析失败。</p><p><strong>原因：</strong> <code>public.easytier.top</code> 这个域名已经不存在了。国内能用的公共节点是社区用户自发部署的，不在官方文档里。</p><p><strong>怎么找到可用节点：</strong></p><ul><li>AstralGame 服务器列表：<a href="https://astral.fan/server-config/server-list" target="_blank" rel="noreferrer">https://astral.fan/server-config/server-list</a></li><li>手动 TCP 连接测试：用 PowerShell 脚本逐个测试端口连通性</li></ul><p><strong>实测可用的国内节点：</strong></p><table tabindex="0"><thead><tr><th>服务器</th><th>地址</th></tr></thead><tbody><tr><td>十堰/未知</td><td><code>tcp://easytier.weiai.org.cn:11010</code></td></tr><tr><td>杭州/家宽</td><td><code>tcp://ros.scpsl.com.cn:11010</code></td></tr><tr><td>张家口/阿里云</td><td><code>tcp://boi.de5.net:11010</code></td></tr></tbody></table><h3 id="_3-leveldb-配置删不掉" tabindex="-1">3. LevelDB 配置删不掉 <a class="header-anchor" href="#_3-leveldb-配置删不掉" aria-label="Permalink to &quot;3. LevelDB 配置删不掉&quot;">​</a></h3><p><strong>症状：</strong> 在 GUI 里删了旧的公共节点，但 LevelDB 里还存着历史记录，进程重启后又加载旧配置。</p><p><strong>原因：</strong> EasyTier GUI 用 WebView2 的 LevelDB 存配置，是 append-only 日志，旧条目不会被删除，只会追加新条目。</p><p><strong>解决：</strong> 关掉 EasyTier → 删除整个 leveldb 文件夹 → 重启自动重建。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>C:\\Users\\a1\\AppData\\Local\\com.kkrainbow.easytier\\EBWebView\\Default\\Local Storage\\leveldb</span></span></code></pre></div><h3 id="_4-跨网段延迟太高-moonlight-没法用" tabindex="-1">4. 跨网段延迟太高，Moonlight 没法用 <a class="header-anchor" href="#_4-跨网段延迟太高-moonlight-没法用" aria-label="Permalink to &quot;4. 跨网段延迟太高，Moonlight 没法用&quot;">​</a></h3><p><strong>症状：</strong> 电脑在 <code>192.168.31.x</code>，手机在 <code>192.168.100.x</code>（随身 WiFi），EasyTier 虚拟网络 ping 延迟 120ms。</p><p><strong>原因：</strong> 两个设备不在同一个局域网，流量走公网中转服务器。而且手机用的 4G 随身 WiFi 有运营商级 NAT（CGNAT），P2P 打洞根本打不通。</p><p><strong>Moonlight 串流要求：</strong> 延迟 &lt;30ms，带宽 &gt;15Mbps。走公网中转的 120ms 完全不可用。</p><p><strong>解决：</strong> 把电脑和手机连到同一个 WiFi，延迟立刻降到 8ms。</p><h3 id="_5-随身-wifi-是一坨" tabindex="-1">5. 随身 WiFi 是一坨 <a class="header-anchor" href="#_5-随身-wifi-是一坨" aria-label="Permalink to &quot;5. 随身 WiFi 是一坨&quot;">​</a></h3><p>手机用的 UFI-5123 随身 WiFi，4G 网络 + CGNAT，P2P 打不通，带宽也拉胯。最后还是得靠家里路由器的 WiFi。</p><h2 id="最终可用配置" tabindex="-1">最终可用配置 <a class="header-anchor" href="#最终可用配置" aria-label="Permalink to &quot;最终可用配置&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>网络名称：daqingda</span></span>
<span class="line"><span>密码：daqingda</span></span>
<span class="line"><span>虚拟 IP：192.168.123.1（电脑）/ 192.168.123.2（手机，DHCP 自动分配）</span></span>
<span class="line"><span>初始节点：tcp://easytier.weiai.org.cn:11010</span></span>
<span class="line"><span>DHCP：关闭</span></span></code></pre></div><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>能不能用</th></tr></thead><tbody><tr><td>同局域网串流</td><td>✅ 8ms 延迟，完美</td></tr><tr><td>跨网串流（走中转）</td><td>❌ 120ms，没法用</td></tr><tr><td>跨网 P2P 打洞</td><td>⚠️ 取决于 NAT 类型，CGNAT 打不通</td></tr><tr><td>文件传输</td><td>✅ 能用，速度取决于带宽</td></tr></tbody></table><p><strong>结论：</strong> EasyTier 适合同局域网或者能成功 P2P 打洞的场景。如果两个设备都在 CGNAT 后面（比如随身 WiFi、校园网），基本只能走中转，延迟高。Moonlight 串流这种对延迟敏感的应用，必须同局域网。</p>`,49)])])}const b=e(i,[["render",o]]);export{g as __pageData,b as default};
